// Minimal re-implementation of the pieces of Python's `argparse` that the
// original script relies on: required string options, `--opt value` and
// `--opt=value` forms, `-h/--help`, prefix abbreviations and the exact
// usage/error text (stderr + exit status 2).

import { basename } from 'node:path';

const MAX_HELP_POSITION = 24;

class ArgumentError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentError';
  }
}

function looksLikeNegativeNumber(text) {
  return /^-\d+$|^-\d*\.\d+$/.test(text);
}

export class ArgumentParser {
  constructor({ prog = null, description = null, addHelp = true } = {}) {
    this.prog = prog === null ? basename(process.argv[1] || 'prog') : prog;
    this.description = description;
    this.actions = [];
    if (addHelp) {
      this.actions.push({
        optionStrings: ['-h', '--help'],
        dest: 'help',
        nargs: 0,
        required: false,
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(...optionStrings) {
    const options = typeof optionStrings[optionStrings.length - 1] === 'object'
      ? optionStrings.pop()
      : {};
    const { required = false, help = null, defaultValue = null } = options;
    const longest = optionStrings.reduce((a, b) => (b.length > a.length ? b : a));
    const dest = longest.replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push({
      optionStrings,
      dest,
      nargs: 1,
      required,
      help,
      defaultValue,
      metavar: options.metavar || dest.toUpperCase(),
    });
    return this;
  }

  // ---- formatting -------------------------------------------------------

  formatUsage() {
    const parts = this.actions.map((action) => {
      const flag = action.optionStrings[0];
      const body = action.nargs === 0 ? flag : `${flag} ${action.metavar}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => (action.nargs === 0
      ? action.optionStrings.join(', ')
      : action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ')));

    const actionMaxLength = invocations.reduce((max, text) => Math.max(max, text.length + 2), 0);
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - 4;

    let out = this.formatUsage();
    if (this.description) out += `\n${this.description}\n`;
    out += '\noptions:\n';
    invocations.forEach((invocation, i) => {
      const { help } = this.actions[i];
      if (!help) {
        out += `  ${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        out += `  ${invocation.padEnd(actionWidth, ' ')}  ${help}\n`;
      } else {
        out += `  ${invocation}\n${' '.repeat(helpPosition)}${help}\n`;
      }
    });
    return out;
  }

  // ---- errors -----------------------------------------------------------

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  // ---- parsing ----------------------------------------------------------

  matchOption(optionString) {
    const exact = this.actions.find((a) => a.optionStrings.includes(optionString));
    if (exact) return { action: exact, used: optionString };

    if (optionString.startsWith('--')) {
      const candidates = [];
      for (const action of this.actions) {
        for (const flag of action.optionStrings) {
          if (flag.startsWith('--') && flag.startsWith(optionString)) {
            candidates.push({ action, used: flag });
          }
        }
      }
      if (candidates.length === 1) return candidates[0];
      if (candidates.length > 1) {
        const names = candidates.map((c) => c.used).join(', ');
        throw new ArgumentError(`ambiguous option: ${optionString} could match ${names}`);
      }
    }
    return null;
  }

  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.nargs !== 0) namespace[action.dest] = action.defaultValue;
    }

    const extras = [];
    const seen = new Set();
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i += 1) {
      const arg = argv[i];

      if (onlyPositionals) {
        extras.push(arg);
        continue;
      }
      if (arg === '--') {
        onlyPositionals = true;
        continue;
      }

      const isOptionLike = arg.length > 1
        && arg.startsWith('-')
        && !looksLikeNegativeNumber(arg)
        && !arg.includes(' ');

      if (!isOptionLike) {
        extras.push(arg);
        continue;
      }

      let name = arg;
      let inlineValue = null;
      const eq = arg.indexOf('=');
      if (arg.startsWith('--') && eq !== -1) {
        name = arg.slice(0, eq);
        inlineValue = arg.slice(eq + 1);
      }

      let match;
      try {
        match = this.matchOption(name);
      } catch (err) {
        this.error(`argument ${name}: ${err.message}`);
        return [namespace, extras];
      }

      if (!match) {
        extras.push(arg);
        continue;
      }

      const { action, used } = match;
      if (action.nargs === 0) {
        if (inlineValue !== null) {
          this.error(`argument ${action.optionStrings.join('/')}: ignored explicit argument '${inlineValue}'`);
        }
        this.printHelp();
        process.exit(0);
      }

      let value = inlineValue;
      if (value === null) {
        const next = argv[i + 1];
        const nextIsOption = next !== undefined
          && next.length > 1
          && next.startsWith('-')
          && !looksLikeNegativeNumber(next)
          && !next.includes(' ');
        if (next === undefined || next === '--' || nextIsOption) {
          this.error(`argument ${used}: expected one argument`);
          return [namespace, extras];
        }
        value = next;
        i += 1;
      }

      namespace[action.dest] = String(value);
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.optionStrings[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parseArgs(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

export default { ArgumentParser };

