// Stand-in for Python's `tempfile.mkdtemp()`: a directory created with mode
// 0o700 inside the platform temp directory, named `<prefix><8 random chars>`.

import { mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomInt } from 'node:crypto';

const NAME_CHARS = 'abcdefghijklmnopqrstuvwxyz0123456789_';
const NAME_LENGTH = 8;
const TMP_MAX = 10000;

function randomName() {
  let name = '';
  for (let i = 0; i < NAME_LENGTH; i += 1) {
    name += NAME_CHARS[randomInt(NAME_CHARS.length)];
  }
  return name;
}

export function gettempdir() {
  return tmpdir();
}

export function mkdtemp({ prefix = 'tmp', suffix = '', dir = null } = {}) {
  const parent = dir === null ? gettempdir() : dir;
  for (let attempt = 0; attempt < TMP_MAX; attempt += 1) {
    const path = join(parent, `${prefix}${randomName()}${suffix}`);
    try {
      mkdirSync(path, { mode: 0o700 });
      return path;
    } catch (err) {
      if (err.code === 'EEXIST') continue;
      throw err;
    }
  }
  throw new Error('No usable temporary directory name found');
}

export default { mkdtemp, gettempdir };

