// Text analysis pipeline: tokenizer -> filters -> tokens.
// Mirrors the behaviour of the default analyzers used by the index fields.

export const STOP_WORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'can', 'for', 'from',
  'have', 'if', 'in', 'is', 'it', 'may', 'not', 'of', 'on', 'or', 'tbd',
  'that', 'the', 'this', 'to', 'us', 'we', 'when', 'will', 'with', 'yet',
  'you', 'your',
]);

// Equivalent of the `\w+(\.?\w+)*` pattern with Python's Unicode-aware `\w`.
const WORD = '[\\p{L}\\p{N}_]';
export const DEFAULT_PATTERN = `${WORD}+(?:\\.?${WORD}+)*`;

export class Token {
  constructor(text, { pos = 0, startchar = 0, endchar = 0, boost = 1.0 } = {}) {
    this.text = text;
    this.pos = pos;
    this.startchar = startchar;
    this.endchar = endchar;
    this.boost = boost;
    this.stopped = false;
  }
}

export class RegexTokenizer {
  constructor(pattern = DEFAULT_PATTERN) {
    this.pattern = pattern;
  }

  run(value) {
    if (typeof value !== 'string') {
      throw new TypeError('RegexTokenizer expects a text value');
    }
    const regex = new RegExp(this.pattern, 'gu');
    const tokens = [];
    let pos = 0;
    let match = regex.exec(value);
    while (match !== null) {
      if (match[0].length === 0) {
        regex.lastIndex += 1;
      } else {
        tokens.push(new Token(match[0], {
          pos,
          startchar: match.index,
          endchar: match.index + match[0].length,
        }));
        pos += 1;
      }
      match = regex.exec(value);
    }
    return tokens;
  }
}

// Emits the whole value as a single token (used by ID fields).
export class IDTokenizer {
  run(value) {
    if (typeof value !== 'string') {
      throw new TypeError('IDTokenizer expects a text value');
    }
    return [new Token(value, { pos: 0, startchar: 0, endchar: value.length })];
  }
}

// Splits on whitespace only (used by KEYWORD fields).
export class SpaceSeparatedTokenizer {
  run(value) {
    const tokens = [];
    const regex = /\S+/gu;
    let pos = 0;
    let match = regex.exec(value);
    while (match !== null) {
      tokens.push(new Token(match[0], {
        pos,
        startchar: match.index,
        endchar: match.index + match[0].length,
      }));
      pos += 1;
      match = regex.exec(value);
    }
    return tokens;
  }
}

export class LowercaseFilter {
  run(tokens) {
    for (const token of tokens) token.text = token.text.toLowerCase();
    return tokens;
  }
}

export class StopFilter {
  constructor({ stoplist = STOP_WORDS, minsize = 2, maxsize = null, renumber = true } = {}) {
    this.stoplist = stoplist === null ? new Set() : new Set(stoplist);
    this.minsize = minsize;
    this.maxsize = maxsize;
    this.renumber = renumber;
  }

  keeps(text) {
    if (text.length < this.minsize) return false;
    if (this.maxsize && text.length > this.maxsize) return false;
    return !this.stoplist.has(text);
  }

  run(tokens) {
    const kept = [];
    let pos = null;
    for (const token of tokens) {
      if (!this.keeps(token.text)) continue;
      if (this.renumber) {
        pos = pos === null ? token.pos : pos + 1;
        token.pos = pos;
      }
      kept.push(token);
    }
    return kept;
  }
}

export class Analyzer {
  constructor(tokenizer, filters = []) {
    this.tokenizer = tokenizer;
    this.filters = filters;
  }

  run(value) {
    let tokens = this.tokenizer.run(value);
    for (const filter of this.filters) tokens = filter.run(tokens);
    return tokens;
  }
}

export function StandardAnalyzer({
  pattern = DEFAULT_PATTERN,
  stoplist = STOP_WORDS,
  minsize = 2,
  maxsize = null,
} = {}) {
  const filters = [new LowercaseFilter()];
  if (stoplist !== null) filters.push(new StopFilter({ stoplist, minsize, maxsize }));
  return new Analyzer(new RegexTokenizer(pattern), filters);
}

export function IDAnalyzer({ lowercase = false } = {}) {
  return new Analyzer(new IDTokenizer(), lowercase ? [new LowercaseFilter()] : []);
}

export function KeywordAnalyzer({ lowercase = false } = {}) {
  return new Analyzer(
    new SpaceSeparatedTokenizer(),
    lowercase ? [new LowercaseFilter()] : [],
  );
}

export function SimpleAnalyzer({ pattern = DEFAULT_PATTERN } = {}) {
  return new Analyzer(new RegexTokenizer(pattern), [new LowercaseFilter()]);
}

