import {
  StandardAnalyzer,
  IDAnalyzer,
  KeywordAnalyzer,
} from './analysis.mjs';

export const Formats = {
  EXISTENCE: 'existence',
  FREQUENCY: 'frequency',
  POSITIONS: 'positions',
};

export class FieldType {
  constructor({
    analyzer = null,
    format = Formats.FREQUENCY,
    stored = false,
    unique = false,
    indexed = true,
    scorable = false,
    fieldBoost = 1.0,
    sortable = false,
  } = {}) {
    this.analyzer = analyzer;
    this.format = format;
    this.stored = stored;
    this.unique = unique;
    this.indexed = indexed;
    this.scorable = scorable;
    this.fieldBoost = fieldBoost;
    this.sortable = sortable;
  }

  get hasPositions() {
    return this.format === Formats.POSITIONS;
  }

  // Turns a field value into `[{ text, positions, frequency }]`.
  index(value) {
    if (!this.indexed) return [];
    const tokens = this.analyzer.run(this.toText(value));
    const grouped = new Map();
    for (const token of tokens) {
      let entry = grouped.get(token.text);
      if (entry === undefined) {
        entry = { text: token.text, frequency: 0, positions: [] };
        grouped.set(token.text, entry);
      }
      entry.frequency += 1;
      if (this.hasPositions) entry.positions.push(token.pos);
    }
    return [...grouped.values()];
  }

  // Analyzes a query string the same way as indexing, returning the terms.
  process_text(value) {
    return this.analyzer.run(this.toText(value)).map((token) => token.text);
  }

