// On-disk storage for index files. Only the small surface the index needs:
// create / open / list / delete named files inside a directory.

import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { join } from 'node:path';

export class StorageError extends Error {
  constructor(message) {
    super(message);
    this.name = 'StorageError';
  }
}

export class FileStorage {
  constructor(path, { readonly = false } = {}) {
    this.folder = path;
    this.readonly = readonly;
  }

  create() {
    if (!existsSync(this.folder)) mkdirSync(this.folder, { recursive: true });
    if (!statSync(this.folder).isDirectory()) {
      throw new StorageError(`${this.folder} is not a directory`);
    }
    return this;
  }

  path(name) {
    return join(this.folder, name);
  }

  fileExists(name) {
    return existsSync(this.path(name));
  }

  listAll() {
    return readdirSync(this.folder).sort();
  }

  // Writes atomically so a half-written file is never visible to a reader.
  writeFile(name, text) {
    if (this.readonly) throw new StorageError('This storage object is read-only');
    const target = this.path(name);
    const temp = `${target}.tmp`;
    writeFileSync(temp, text, 'utf8');
    renameSync(temp, target);
  }

  readFile(name) {
    if (!this.fileExists(name)) {
      throw new StorageError(`No such file ${JSON.stringify(name)}`);
    }
    return readFileSync(this.path(name), 'utf8');
  }

  deleteFile(name) {
    if (this.readonly) throw new StorageError('This storage object is read-only');
    rmSync(this.path(name), { force: true });
  }
}

// In-memory equivalent, useful for tests and transient indexes.
export class RamStorage {
  constructor() {
    this.files = new Map();
    this.readonly = false;
  }

  create() {
    return this;
  }

  fileExists(name) {
    return this.files.has(name);
  }

  listAll() {
    return [...this.files.keys()].sort();
  }

  writeFile(name, text) {
    this.files.set(name, text);
  }

  readFile(name) {
    if (!this.files.has(name)) {
      throw new StorageError(`No such file ${JSON.stringify(name)}`);
    }
    return this.files.get(name);
  }

  deleteFile(name) {
    this.files.delete(name);
  }
}

