// Serialization of a segment (postings + stored fields + length data) and of
// the table of contents that ties segments to a schema.

import { Schema, FieldType } from './fields.mjs';

export const TOC_VERSION = 1;

export class Segment {
  constructor(name) {
    this.name = name;
    this.docCount = 0;
    // fieldname -> term -> { docFreq, postings: [{ docnum, frequency, positions }] }
    this.terms = new Map();
    this.storedFields = [];
    // fieldname -> array of per-document lengths
    this.lengths = new Map();
    this.deleted = new Set();
  }

  get segmentFileName() {
    return `${this.name}.seg`;
  }

  toJSON() {
    const terms = {};
    for (const [fieldname, termMap] of this.terms) {
      const dumped = {};
      for (const [text, entry] of termMap) {
        dumped[text] = entry.postings.map((p) => (
          p.positions.length ? [p.docnum, p.frequency, p.positions] : [p.docnum, p.frequency]
        ));
      }
      terms[fieldname] = dumped;
    }
    const lengths = {};
    for (const [fieldname, values] of this.lengths) lengths[fieldname] = values;
    return {
      name: this.name,
      docCount: this.docCount,
      terms,
      lengths,
      storedFields: this.storedFields,
      deleted: [...this.deleted],
    };
  }

  static fromJSON(data) {
    const segment = new Segment(data.name);
    segment.docCount = data.docCount;
    segment.storedFields = data.storedFields;
    segment.deleted = new Set(data.deleted || []);
    for (const [fieldname, dumped] of Object.entries(data.terms)) {
      const termMap = new Map();
      for (const [text, rows] of Object.entries(dumped)) {
        const postings = rows.map(([docnum, frequency, positions = []]) => ({
          docnum,
          frequency,
          positions,
        }));
        termMap.set(text, { docFreq: postings.length, postings });
      }
      segment.terms.set(fieldname, termMap);
    }
    for (const [fieldname, values] of Object.entries(data.lengths)) {
      segment.lengths.set(fieldname, values);
    }
    return segment;
  }
}

function dumpSchema(schema) {
  const fields = {};
  for (const [name, field] of schema) {
    fields[name] = {
      format: field.format,
      stored: field.stored,
      unique: field.unique,
      indexed: field.indexed,
      scorable: field.scorable,
      fieldBoost: field.fieldBoost,
      sortable: field.sortable,
    };
  }
  return fields;
}

// The schema is rebuilt from its structural description; analyzers are
// re-attached from the live schema when the index is re-opened in-process.
function loadSchema(dumped, analyzers) {
  const schema = new Schema();
  for (const [name, spec] of Object.entries(dumped)) {
    schema.add(name, new FieldType({ ...spec, analyzer: analyzers.get(name) || null }));
  }
  return schema;
}

export function encodeToc({ schema, generation, segments }) {
  return JSON.stringify({
    version: TOC_VERSION,
    generation,
    schema: dumpSchema(schema),
    segments: segments.map((segment) => segment.name),
  }, null, 1);
}

export function decodeToc(text, analyzers) {
  const data = JSON.parse(text);
  if (data.version !== TOC_VERSION) {
    throw new Error(`Unsupported index version ${data.version}`);
  }
  return {
    generation: data.generation,
    schema: loadSchema(data.schema, analyzers),
    segmentNames: data.segments,
  };
}

export function encodeSegment(segment) {
  return JSON.stringify(segment.toJSON());
}

export function decodeSegment(text) {
  return Segment.fromJSON(JSON.parse(text));
}

