// Writes documents into a new segment and publishes it on commit.

import { Segment, encodeSegment, encodeToc } from './codec.mjs';
import { UnknownFieldError } from './fields.mjs';
import { randomName } from './util.mjs';

export class IndexingError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IndexingError';
  }
}

export class IndexWriter {
  constructor(index) {
    this.index = index;
    this.schema = index.schema;
    this.storage = index.storage;
    this.segment = new Segment(`${index.indexname}_${randomName(12)}`);
    this.closed = false;
    this._uniqueTerms = [];
  }

  _checkOpen() {
    if (this.closed) throw new IndexingError('This writer is closed');
  }

  addDocument(fields = {}) {
    this._checkOpen();

    for (const name of Object.keys(fields)) {
      if (!this.schema.has(name)) throw new UnknownFieldError(name);
    }

    const docnum = this.segment.docCount;
    const stored = {};

    for (const [name, field] of this.schema) {
      const value = fields[name];
      const missing = value === undefined || value === null;

      if (field.stored && !missing) stored[name] = value;
      if (missing || !field.indexed) {
        if (field.scorable) this._recordLength(name, docnum, 0);
        continue;
      }

      const entries = field.index(value);
      let length = 0;
      for (const entry of entries) {
        length += entry.frequency;
        this._addPosting(name, entry, docnum);
      }
      if (field.scorable) this._recordLength(name, docnum, length);
      if (field.unique) {
        for (const entry of entries) this._uniqueTerms.push([name, entry.text]);
      }
    }

    this.segment.storedFields.push(stored);
    this.segment.docCount += 1;
    return docnum;
  }

  // Python-style keyword call: `writer.add_document({ title, content })`.
  add_document(fields) {
    return this.addDocument(fields);
  }

  _addPosting(fieldname, entry, docnum) {
    let termMap = this.segment.terms.get(fieldname);
    if (termMap === undefined) {
      termMap = new Map();
      this.segment.terms.set(fieldname, termMap);
    }
    let posting = termMap.get(entry.text);
    if (posting === undefined) {
      posting = { docFreq: 0, postings: [] };
      termMap.set(entry.text, posting);
    }
    posting.postings.push({
      docnum,
      frequency: entry.frequency,
      positions: entry.positions,
    });
    posting.docFreq = posting.postings.length;
  }

  _recordLength(fieldname, docnum, length) {
    let lengths = this.segment.lengths.get(fieldname);
    if (lengths === undefined) {
      lengths = [];
      this.segment.lengths.set(fieldname, lengths);
    }
    while (lengths.length < docnum) lengths.push(0);
    lengths[docnum] = length;
  }

  deleteByTerm(fieldname, text) {
    this._checkOpen();
    const termMap = this.segment.terms.get(fieldname);
    if (!termMap || !termMap.has(text)) return 0;
    let count = 0;
    for (const posting of termMap.get(text).postings) {
      if (!this.segment.deleted.has(posting.docnum)) {
        this.segment.deleted.add(posting.docnum);
        count += 1;
      }
    }
    return count;
  }

  commit({ merge = true } = {}) {
    this._checkOpen();
    // Pad every length vector so index lookups by docnum are always defined.
    for (const values of this.segment.lengths.values()) {
      while (values.length < this.segment.docCount) values.push(0);
    }

    const segments = merge ? [...this.index.segments] : [];
    if (this.segment.docCount > 0) {
      this.storage.writeFile(this.segment.segmentFileName, encodeSegment(this.segment));
      segments.push(this.segment);
    }

    const generation = this.index.generation + 1;
    this.storage.writeFile(
      this.index.tocFileName(generation),
      encodeToc({ schema: this.schema, generation, segments }),
    );
    this.index._advance(generation, segments);
    this.closed = true;
  }

  cancel() {
    this.closed = true;
  }
}

