const CHARS = 'abcdefghijklmnopqrstuvwxyz0123456789';

export function randomName(length = 12) {
  let name = '';
  for (let i = 0; i < length; i += 1) name += CHARS[randomInt(CHARS.length)];
  return name;
}

export function sortedUnique(numbers) {
  return [...new Set(numbers)].sort((a, b) => a - b);
}

