// Read-only view over the committed segments of an index.

export class SegmentReader {
  constructor(segment, schema, offset = 0) {
    this.segment = segment;
    this.schema = schema;
    this.offset = offset;
  }

  docCount() {
    return this.segment.docCount - this.segment.deleted.size;
  }

  docCountAll() {
    return this.segment.docCount;
  }

  isDeleted(docnum) {
    return this.segment.deleted.has(docnum);
  }

  allDocIds() {
    const ids = [];
    for (let i = 0; i < this.segment.docCount; i += 1) {
      if (!this.isDeleted(i)) ids.push(i + this.offset);
    }
    return ids;
  }

  storedFields(docnum) {
    return this.segment.storedFields[docnum - this.offset] || {};
  }

  hasTerm(fieldname, text) {
    const termMap = this.segment.terms.get(fieldname);
    return Boolean(termMap && termMap.has(text));
  }

  docFrequency(fieldname, text) {
    const termMap = this.segment.terms.get(fieldname);
    if (!termMap || !termMap.has(text)) return 0;
    return termMap.get(text).postings
      .filter((p) => !this.isDeleted(p.docnum)).length;
  }

  // Postings for a term, with document numbers shifted into global space.
  postings(fieldname, text) {
    const termMap = this.segment.terms.get(fieldname);
    if (!termMap || !termMap.has(text)) return [];
    return termMap.get(text).postings
      .filter((p) => !this.isDeleted(p.docnum))
      .map((p) => ({
        docnum: p.docnum + this.offset,
        frequency: p.frequency,
        positions: p.positions,
      }));
  }

  fieldTerms(fieldname) {
    const termMap = this.segment.terms.get(fieldname);
    return termMap ? [...termMap.keys()].sort() : [];
  }

  // Documents that actually have content in the given field.
  fieldDocIds(fieldname) {
    const found = new Set();
    const termMap = this.segment.terms.get(fieldname);
    if (termMap) {
      for (const entry of termMap.values()) {
        for (const posting of entry.postings) {
          if (!this.isDeleted(posting.docnum)) found.add(posting.docnum + this.offset);
        }
      }
    }
    const field = this.schema.has(fieldname) ? this.schema.get(fieldname) : null;
    if (field && !field.indexed) {
      for (let i = 0; i < this.segment.docCount; i += 1) {
        if (this.isDeleted(i)) continue;
        if (this.segment.storedFields[i] && fieldname in this.segment.storedFields[i]) {
          found.add(i + this.offset);
        }
      }
    }
    return [...found].sort((a, b) => a - b);
  }

  docFieldLength(docnum, fieldname) {
    const lengths = this.segment.lengths.get(fieldname);
    if (!lengths) return 0;
    return lengths[docnum - this.offset] || 0;
  }

  fieldLength(fieldname) {
    const lengths = this.segment.lengths.get(fieldname);
    if (!lengths) return 0;
    let total = 0;
    for (let i = 0; i < lengths.length; i += 1) {
      if (!this.isDeleted(i)) total += lengths[i];
    }
    return total;
  }
}

// Presents several segments as one contiguous document space.
export class MultiReader {
  constructor(segments, schema) {
    this.schema = schema;
    this.readers = [];
    let offset = 0;
    for (const segment of segments) {
      this.readers.push(new SegmentReader(segment, schema, offset));
      offset += segment.docCount;
    }
    this.total = offset;
  }

  docCount() {
    return this.readers.reduce((sum, reader) => sum + reader.docCount(), 0);
  }

  docCountAll() {
    return this.total;
  }

  allDocIds() {
    const ids = [];
    for (const reader of this.readers) ids.push(...reader.allDocIds());
    return ids;
  }

  _readerFor(docnum) {
    for (const reader of this.readers) {
      if (docnum >= reader.offset && docnum < reader.offset + reader.docCountAll()) {
        return reader;
      }
    }
    return null;
  }

  storedFields(docnum) {
    const reader = this._readerFor(docnum);
    return reader ? reader.storedFields(docnum) : {};
  }

  hasTerm(fieldname, text) {
    return this.readers.some((reader) => reader.hasTerm(fieldname, text));
  }

  docFrequency(fieldname, text) {
    return this.readers.reduce((sum, r) => sum + r.docFrequency(fieldname, text), 0);
  }

  postings(fieldname, text) {
    const out = [];
    for (const reader of this.readers) out.push(...reader.postings(fieldname, text));
    return out;
  }

  fieldTerms(fieldname) {
    const terms = new Set();
    for (const reader of this.readers) {
      for (const term of reader.fieldTerms(fieldname)) terms.add(term);
    }
    return [...terms].sort();
  }

  fieldDocIds(fieldname) {
    const ids = [];
    for (const reader of this.readers) ids.push(...reader.fieldDocIds(fieldname));
    return ids.sort((a, b) => a - b);
  }

  docFieldLength(docnum, fieldname) {
    const reader = this._readerFor(docnum);
    return reader ? reader.docFieldLength(docnum, fieldname) : 0;
  }

  fieldLength(fieldname) {
    return this.readers.reduce((sum, r) => sum + r.fieldLength(fieldname), 0);
  }

  avgFieldLength(fieldname) {
    const count = this.docCount();
    if (!count) return 0;
    return this.fieldLength(fieldname) / count;
  }
}

