// Relevance scoring. BM25F is the default weighting model.

export class WeightingModel {
  scorer(searcher, fieldname, text) {
    throw new Error('Not implemented');
  }
}

class BM25FScorer {
  constructor(searcher, fieldname, { B = 0.75, K1 = 1.2 } = {}) {
    this.searcher = searcher;
    this.fieldname = fieldname;
    this.B = B;
    this.K1 = K1;
    this.avgFieldLength = searcher.reader.avgFieldLength(fieldname) || 1;
    this.docCount = searcher.docCount() || 1;
  }

  idf(docFreq) {
    const n = this.docCount;
    return Math.log(((n - docFreq + 0.5) / (docFreq + 0.5)) + 1.0);
  }

  score(docnum, frequency, docFreq) {
    const length = this.searcher.reader.docFieldLength(docnum, this.fieldname)
      || this.avgFieldLength;
    const norm = 1 - this.B + (this.B * (length / this.avgFieldLength));
    return this.idf(docFreq)
      * ((frequency * (this.K1 + 1)) / (frequency + (this.K1 * norm)));
  }
}

export class BM25F extends WeightingModel {
  constructor({ B = 0.75, K1 = 1.2 } = {}) {
    super();
    this.B = B;
    this.K1 = K1;
  }

  scorer(searcher, fieldname) {
    return new BM25FScorer(searcher, fieldname, { B: this.B, K1: this.K1 });
  }
}

// Every matching document scores 1.0 (used by queries with no term weight).
export class Frequency extends WeightingModel {
  scorer() {
    return { score: (docnum, frequency) => frequency };
  }
}

export const defaultWeighting = () => new BM25F();

