// Matchers walk the documents that satisfy a query, in document order.

export class Matcher {
  isActive() { return false; }
  id() { throw new Error('Matcher is exhausted'); }
  score() { return 0; }
  next() {}

  // Convenience: drain the matcher into `[{ docnum, score }]`.
  all() {
    const out = [];
    while (this.isActive()) {
      out.push({ docnum: this.id(), score: this.score() });
      this.next();
    }
    return out;
  }
}

export class NullMatcher extends Matcher {}

export class ListMatcher extends Matcher {
  // `entries` must be `[{ docnum, score }]` sorted by docnum.
  constructor(entries) {
    super();
    this.entries = entries;
    this.i = 0;
  }

  isActive() { return this.i < this.entries.length; }
  id() { return this.entries[this.i].docnum; }
  score() { return this.entries[this.i].score; }
  next() { this.i += 1; }
}

function activeChildren(children) {
  return children.filter((child) => child.isActive());
}

export class UnionMatcher extends Matcher {
  constructor(children) {
    super();
    this.children = children;
  }

  isActive() { return activeChildren(this.children).length > 0; }

  id() {
    return Math.min(...activeChildren(this.children).map((child) => child.id()));
  }

  score() {
    const current = this.id();
    return this.children
      .filter((child) => child.isActive() && child.id() === current)
      .reduce((sum, child) => sum + child.score(), 0);
  }

  next() {
    const current = this.id();
    for (const child of this.children) {
      if (child.isActive() && child.id() === current) child.next();
    }
  }
}

export class IntersectionMatcher extends Matcher {
  constructor(children) {
    super();
    this.children = children;
    this._align();
  }

  _align() {
    if (!this.children.length) return;
    for (;;) {
      if (this.children.some((child) => !child.isActive())) return;
      const ids = this.children.map((child) => child.id());
      const highest = Math.max(...ids);
      if (ids.every((id) => id === highest)) return;
      for (const child of this.children) {
        while (child.isActive() && child.id() < highest) child.next();
      }
    }
  }

  isActive() {
    return this.children.length > 0 && this.children.every((child) => child.isActive());
  }

  id() { return this.children[0].id(); }

  score() {
    return this.children.reduce((sum, child) => sum + child.score(), 0);
  }

  next() {
    for (const child of this.children) child.next();
    this._align();
  }
}

export class AndNotMatcher extends Matcher {
  constructor(positive, negative) {
    super();
    this.positive = positive;
    this.negative = negative;
    this._skip();
  }

  _skip() {
    while (this.positive.isActive()) {
      const id = this.positive.id();
      while (this.negative.isActive() && this.negative.id() < id) this.negative.next();
      if (this.negative.isActive() && this.negative.id() === id) {
        this.positive.next();
      } else {
        return;
      }
    }
  }

  isActive() { return this.positive.isActive(); }
  id() { return this.positive.id(); }
  score() { return this.positive.score(); }

  next() {
    this.positive.next();
    this._skip();
  }
}

