// how to estimate the number of documents it will match.

import {
  ListMatcher,
  NullMatcher,
  UnionMatcher,
  IntersectionMatcher,
  AndNotMatcher,
} from './matching.mjs';

export class Query {
  matcher(searcher) {
    return new NullMatcher();
  }

  estimateSize(reader) {
    return 0;
  }

  docs(searcher) {
    const found = [];
    const matcher = this.matcher(searcher);
    while (matcher.isActive()) {
      found.push(matcher.id());
      matcher.next();
    }
    return found;
  }

  normalize() {
    return this;
  }

  toString() {
    return this.constructor.name;
  }
}

export class NullQuery extends Query {
  toString() { return '<NullQuery>'; }
}

// Matches every document (optionally, every document containing a field).
export class Every extends Query {
  constructor(fieldname = null, { boost = 1.0 } = {}) {
    super();
    this.fieldname = fieldname;
    this.boost = boost;
  }

  estimateSize(reader) {
    return this.fieldname === null || this.fieldname === '*'
      ? reader.docCount()
      : reader.fieldDocIds(this.fieldname).length;
  }

  matcher(searcher) {
    const { reader } = searcher;
    const ids = this.fieldname === null || this.fieldname === '*'
      ? reader.allDocIds()
      : reader.fieldDocIds(this.fieldname);
    return new ListMatcher(ids.map((docnum) => ({ docnum, score: this.boost })));
  }

  toString() {
    return this.fieldname === null ? 'Every()' : `Every(${this.fieldname})`;
  }
}

export class Term extends Query {
  constructor(fieldname, text, { boost = 1.0 } = {}) {
    super();
    this.fieldname = fieldname;
    this.text = text;
    this.boost = boost;
  }

  estimateSize(reader) {
    return reader.docFrequency(this.fieldname, this.text);
  }

  matcher(searcher) {
    const postings = searcher.reader.postings(this.fieldname, this.text);
    if (!postings.length) return new NullMatcher();
    const docFreq = postings.length;
    const scorer = searcher.scorer(this.fieldname);
    const entries = postings
      .sort((a, b) => a.docnum - b.docnum)
      .map((posting) => ({
        docnum: posting.docnum,
        score: this.boost * scorer.score(posting.docnum, posting.frequency, docFreq),
      }));
    return new ListMatcher(entries);
  }

