  constructor(subqueries, { boost = 1.0 } = {}) {
    super();
    this.subqueries = subqueries;
    this.boost = boost;
  }

  normalize() {
    const kept = this.subqueries
      .map((q) => q.normalize())
      .filter((q) => !(q instanceof NullQuery));
