// Collectors gather the documents produced by a matcher.
// The top collector keeps the best `limit` hits while still counting every
// document the query matched.

export class Collector {
  constructor() {
    this.total = 0;
  }

  collect(docnum, score) {}

  run(matcher) {
    while (matcher.isActive()) {
      this.total += 1;
      this.collect(matcher.id(), matcher.score());
      matcher.next();
    }
    return this;
  }
}

export class TopCollector extends Collector {
  constructor(limit = 10, { reverse = false } = {}) {
    super();
    this.limit = limit === null ? null : Math.max(0, limit);
    this.reverse = reverse;
    this.hits = [];
  }

  collect(docnum, score) {
    this.hits.push({ docnum, score });
  }

  // Sorted by descending score, ties broken by ascending document number.
  results() {
    const ordered = [...this.hits].sort((a, b) => (
      b.score - a.score || a.docnum - b.docnum
    ));
    if (this.reverse) ordered.reverse();
    return this.limit === null ? ordered : ordered.slice(0, this.limit);
  }
}

export class UnlimitedCollector extends TopCollector {
  constructor() {
    super(null);
  }
}

export class DocsCollector extends Collector {
  constructor() {
    super();
    this.docs = [];
  }

  collect(docnum) {
    this.docs.push(docnum);
  }
}

