// Searcher, Results and Hit.

import { TopCollector } from './collectors.mjs';
import { defaultWeighting } from './scoring.mjs';

export class Hit {
  constructor(results, docnum, rank, score) {
    this.results = results;
    this.docnum = docnum;
    this.rank = rank;
    this.score = score;
    this._fields = null;
  }

  fields() {
    if (this._fields === null) {
      this._fields = this.results.searcher.storedFields(this.docnum);
    }
    return this._fields;
  }

  get(key, fallback = null) {
    const fields = this.fields();
    return key in fields ? fields[key] : fallback;
  }

  keys() { return Object.keys(this.fields()); }
  values() { return Object.values(this.fields()); }
  items() { return Object.entries(this.fields()); }
}

export class Results {
  constructor(searcher, query, hits, totalCount, runtime) {
    this.searcher = searcher;
    this.query = query;
    this.topN = hits;
    this._total = totalCount;
    this.runtime = runtime;
  }

  // Total number of documents the query matched; this may be greater than the
  // number of ranked hits held in `topN`.
  length() {
    return this._total;
  }

  scoredLength() {
    return this.topN.length;
  }

  isEmpty() {
    return this._total === 0;
  }

  docs() {
    return this.topN.map((hit) => hit.docnum);
  }

  get(index) {
    const hit = this.topN[index];
    return hit === undefined ? undefined : new Hit(this, hit.docnum, index, hit.score);
  }

  score(index) {
    const hit = this.topN[index];
    return hit === undefined ? null : hit.score;
  }

  *[Symbol.iterator]() {
    for (let i = 0; i < this.topN.length; i += 1) yield this.get(i);
  }
}

export class Searcher {
  constructor(reader, { weighting = null, schema = null, closepool = true } = {}) {
    this.reader = reader;
    this.schema = schema || reader.schema;
    this.weighting = weighting || defaultWeighting();
    this.closepool = closepool;
    this.closed = false;
    this._scorers = new Map();
  }

  docCount() {
    return this.reader.docCount();
  }

  docCountAll() {
    return this.reader.docCountAll();
  }

  storedFields(docnum) {
    return this.reader.storedFields(docnum);
  }

  scorer(fieldname) {
    let scorer = this._scorers.get(fieldname);
    if (scorer === undefined) {
      scorer = this.weighting.scorer(this, fieldname);
      this._scorers.set(fieldname, scorer);
    }
    return scorer;
  }

  documentNumbers(query) {
    return query.docs(this);
  }

  search(query, { limit = 10, scored = true, reverse = false } = {}) {
    const started = Date.now();
    const collector = new TopCollector(limit, { reverse });
    collector.run(query.matcher(this));
    const ranked = scored
      ? collector.results()
      : collector.hits.slice(0, limit === null ? undefined : limit);
    const runtime = (Date.now() - started) / 1000;
    return new Results(this, query, ranked, collector.total, runtime);
  }

  close() {
    this.closed = true;
  }
}

