  }

  scorer(fieldname) {
    let scorer = this._scorers.get(fieldname);
    if (scorer === undefined) {
      scorer = this.weighting.scorer(this, fieldname);
      this._scorers.set(fieldname, scorer);
    }
    return scorer;
  }

  documentNumbers(query) {
    return query.docs(this);
  }

  search(query, { limit = 10, scored = true, reverse = false } = {}) {
    const started = Date.now();
    const collector = new TopCollector(limit, { reverse });
    collector.run(query.matcher(this));
    const ranked = scored
      ? collector.results()
      : collector.hits.slice(0, limit === null ? undefined : limit);
    const runtime = (Date.now() - started) / 1000;
    return new Results(this, query, ranked, collector.total, runtime);
  }

  close() {
    this.closed = true;
  }
}

