// Index creation and opening, plus the FileIndex object returned by
// `createIn` / `openDir`.

import { existsSync, statSync } from 'node:fs';
import { FileStorage } from './storage.mjs';
import { decodeSegment, decodeToc, encodeToc } from './codec.mjs';
import { MultiReader } from './reading.mjs';
import { IndexWriter } from './writing.mjs';
import { Searcher } from './searching.mjs';

export const DEFAULT_INDEX_NAME = 'MAIN';

export class EmptyIndexError extends Error {
  constructor(message) {
    super(message);
    this.name = 'EmptyIndexError';
  }
}

function tocPattern(indexname) {
  return new RegExp(`^_${indexname}_(\\d+)\\.toc$`);
}

function latestGeneration(storage, indexname) {
  const pattern = tocPattern(indexname);
  let best = -1;
  for (const name of storage.listAll()) {
    const match = pattern.exec(name);
    if (match) best = Math.max(best, Number(match[1]));
  }
  return best;
}

export class FileIndex {
  constructor(storage, { indexname = DEFAULT_INDEX_NAME, schema = null } = {}) {
    this.storage = storage;
    this.indexname = indexname;
    this.schema = schema;
    this.generation = -1;
    this.segments = [];
  }

  tocFileName(generation = this.generation) {
    return `_${this.indexname}_${generation}.toc`;
  }

  _advance(generation, segments) {
    this.generation = generation;
    this.segments = segments;
  }

  _load() {
    const generation = latestGeneration(this.storage, this.indexname);
    if (generation < 0) {
      throw new EmptyIndexError(`Index ${JSON.stringify(this.indexname)} does not exist`);
    }
    const analyzers = new Map();
    if (this.schema) {
      for (const [name, field] of this.schema) analyzers.set(name, field.analyzer);
    }
    const toc = decodeToc(this.storage.readFile(this.tocFileName(generation)), analyzers);
    if (!this.schema) this.schema = toc.schema;
    this.generation = toc.generation;
    this.segments = toc.segmentNames.map(
      (name) => decodeSegment(this.storage.readFile(`${name}.seg`)),
    );
    return this;
  }

  writer() {
    return new IndexWriter(this);
  }

  reader() {
    return new MultiReader(this.segments, this.schema);
  }

  searcher(options = {}) {
    return new Searcher(this.reader(), { schema: this.schema, ...options });
  }

  docCount() {
    return this.reader().docCount();
  }

  isEmpty() {
    return this.docCount() === 0;
  }

  latestGeneration() {
    return latestGeneration(this.storage, this.indexname);
  }

  close() {}
}

export function createIn(dirname, schema, indexname = DEFAULT_INDEX_NAME) {
  if (!existsSync(dirname) || !statSync(dirname).isDirectory()) {
    throw new Error(`${dirname} is not a directory`);
  }
  const storage = new FileStorage(dirname).create();
  const index = new FileIndex(storage, { indexname, schema });
  // An empty index still has a table of contents at generation 0.
  storage.writeFile(index.tocFileName(0), encodeToc({ schema, generation: 0, segments: [] }));
  index._advance(0, []);
  return index;
}

export function openDir(dirname, { indexname = DEFAULT_INDEX_NAME, schema = null } = {}) {
  const storage = new FileStorage(dirname);
  return new FileIndex(storage, { indexname, schema })._load();
}

export function existsIn(dirname, indexname = DEFAULT_INDEX_NAME) {
  if (!existsSync(dirname) || !statSync(dirname).isDirectory()) return false;
  return latestGeneration(new FileStorage(dirname), indexname) >= 0;
}

