// A small query-language parser: bare terms, quoted phrases, field prefixes,
// AND / OR / NOT operators, grouping with parentheses, and required (+) or
// excluded (-) terms.

import {
  And, AndNot, Every, Not, NullQuery, Or, Phrase, Term,
} from './query.mjs';

const TOKEN = /\s*(\(|\)|"[^"]*"|[^\s()"]+)/y;

function tokenize(text) {
  const tokens = [];
  TOKEN.lastIndex = 0;
  let match = TOKEN.exec(text);
  while (match !== null) {
    tokens.push(match[1]);
    TOKEN.lastIndex = match.index + match[0].length;
    match = TOKEN.exec(text);
  }
  return tokens;
}

export class QueryParser {
  constructor(fieldname, schema, { group = Or, plugins = [] } = {}) {
    this.fieldname = fieldname;
    this.schema = schema;
    this.group = group;
    this.plugins = plugins;
  }

  _analyze(fieldname, text) {
    if (this.schema && this.schema.has(fieldname)) {
      return this.schema.get(fieldname).process_text(text);
    }
    return [text.toLowerCase()];
  }

  _leaf(token) {
    let fieldname = this.fieldname;
    let body = token;

    const colon = token.indexOf(':');
    if (colon > 0 && this.schema && this.schema.has(token.slice(0, colon))) {
      fieldname = token.slice(0, colon);
      body = token.slice(colon + 1);
    }

    if (body === '*' || body === '') return new Every(fieldname);

    if (body.startsWith('"') && body.endsWith('"') && body.length >= 2) {
      const words = this._analyze(fieldname, body.slice(1, -1));
      if (!words.length) return new NullQuery();
      if (words.length === 1) return new Term(fieldname, words[0]);
      return new Phrase(fieldname, words);
    }

    const words = this._analyze(fieldname, body);
    if (!words.length) return new NullQuery();
    if (words.length === 1) return new Term(fieldname, words[0]);
    return new And(words.map((word) => new Term(fieldname, word)));
  }

  parse(text) {
    const tokens = tokenize(String(text));
    const state = { i: 0 };
    const query = this._parseGroup(tokens, state, false);
    return query.normalize();
  }

  _parseGroup(tokens, state, nested) {
    const clauses = [];
    const required = [];
    const excluded = [];
    let operator = null;
    let negateNext = false;

    const push = (query) => {
      if (query instanceof NullQuery) return;
      if (negateNext) {
        excluded.push(query);
        negateNext = false;
        return;
      }
      clauses.push(query);
    };

    while (state.i < tokens.length) {
      const token = tokens[state.i];
      state.i += 1;

      if (token === '(') {
        push(this._parseGroup(tokens, state, true));
        continue;
      }
      if (token === ')') {
        if (nested) break;
        continue;
      }

      const upper = token.toUpperCase();
      if (upper === 'AND') { operator = And; continue; }
      if (upper === 'OR') { operator = Or; continue; }
      if (upper === 'NOT') { negateNext = true; continue; }

      if (token.startsWith('-') && token.length > 1) {
        excluded.push(this._leaf(token.slice(1)));
        continue;
      }
      if (token.startsWith('+') && token.length > 1) {
        required.push(this._leaf(token.slice(1)));
        continue;
      }

      push(this._leaf(token));
    }

    const Group = operator || this.group;
    let combined;
    const positives = [...clauses, ...required];
    if (!positives.length) {
      combined = excluded.length ? new Every() : new NullQuery();
    } else if (required.length && clauses.length) {
      combined = new And([new Group(clauses), ...required]);
    } else if (positives.length === 1) {
      [combined] = positives;
    } else {
      combined = required.length ? new And(positives) : new Group(positives);
    }

    if (excluded.length) {
      const negative = excluded.length === 1 ? excluded[0] : new Or(excluded);
      combined = combined instanceof NullQuery
        ? new Not(negative)
        : new AndNot(combined, negative);
    }
    return combined;
  }
}

export function MultifieldParser(fieldnames, schema, options = {}) {
  const parser = new QueryParser(fieldnames[0], schema, options);
  const parseOne = parser.parse.bind(parser);
  parser.parse = (text) => {
    const parts = fieldnames.map((name) => {
      const sub = new QueryParser(name, schema, options);
      return sub.parse(text);
    }).filter((q) => !(q instanceof NullQuery));
    if (!parts.length) return new NullQuery();
    return parts.length === 1 ? parts[0] : new Or(parts).normalize();
  };
  parser.parseSingleField = parseOne;
  return parser;
}

